Listen up. We have tests. We have nothing else. Time to build what we need and nothing more.

```go
package cart

import "errors"

var ErrItemNotFound = errors.New("item not found")

type Item struct {
	SKU      string
	Name     string
	Price    float64
	Quantity int
}

type ShoppingCart struct {
	items map[string]*Item
}

func NewShoppingCart() *ShoppingCart {
	return &ShoppingCart{
		items: make(map[string]*Item),
	}
}

func (c *ShoppingCart) AddItem(sku, name string, price float64, quantity int) {
	if existing, ok := c.items[sku]; ok {
		existing.Quantity += quantity
		return
	}
	c.items[sku] = &Item{
		SKU:      sku,
		Name:     name,
		Price:    price,
		Quantity: quantity,
	}
}

func (c *ShoppingCart) RemoveItem(sku string) error {
	if _, ok := c.items[sku]; !ok {
		return ErrItemNotFound
	}
	delete(c.items, sku)
	return nil
}

func (c *ShoppingCart) UpdateQuantity(sku string, quantity int) error {
	item, ok := c.items[sku]
	if !ok {
		return ErrItemNotFound
	}
	if quantity <= 0 {
		delete(c.items, sku)
		return nil
	}
	item.Quantity = quantity
	return nil
}

func (c *ShoppingCart) GetItem(sku string) (*Item, error) {
	item, ok := c.items[sku]
	if !ok {
		return nil, ErrItemNotFound
	}
	return item, nil
}

func (c *ShoppingCart) GetItems() []*Item {
	result := make([]*Item, 0, len(c.items))
	for _, item := range c.items {
		result = append(result, item)
	}
	return result
}

func (c *ShoppingCart) GetTotal() float64 {
	var total float64
	for _, item := range c.items {
		total += item.Price * float64(item.Quantity)
	}
	return total
}

func (c *ShoppingCart) GetItemCount() int {
	var count int
	for _, item := range c.items {
		count += item.Quantity
	}
	return count
}

func (c *ShoppingCart) Clear() {
	c.items = make(map[string]*Item)
}

func (c *ShoppingCart) IsEmpty() bool {
	return len(c.items) == 0
}
```

*leans back*

That's the ship. Nothing fancy. Nothing we don't need.

- `NewShoppingCart` creates empty cart with initialized map
- `AddItem` adds or increments quantity for existing SKU
- `RemoveItem` deletes or returns error if not found
- `UpdateQuantity` changes quantity, removes item if zero or less
- `GetItem` retrieves single item or error
- `GetItems` returns slice of all items
- `GetTotal` calculates price times quantity across all items
- `GetItemCount` sums all quantities
- `Clear` resets the cart
- `IsEmpty` checks if anything's in there

No validation on negative prices. No discount systems. No persistence. The tests didn't ask for it, so it doesn't exist.

You want to survive out here, you build exactly what you need. Nothing more weighs you down. Nothing less gets you killed.

